// Runs only in a disposable clean Windows VM. Requires no guest development tools.
using System;using System.IO;using System.Linq;using System.Diagnostics;using System.Threading;using System.Windows.Automation;using System.Web.Script.Serialization;using System.Collections.Generic;using System.Net;using System.Text;using System.Security.Cryptography;using Microsoft.Win32;using System.Drawing;using System.Windows.Forms;using System.Management;
class GuestChecks {
static string results=@"C:\ScriptStudio-TestResults",home=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),app,storage,setup,url;static JavaScriptSerializer json=new JavaScriptSerializer();static AutomationElement root;static List<string> passed=new List<string>();
static void Status(string s){Directory.CreateDirectory(results);File.AppendAllText(Path.Combine(results,"progress.log"),DateTime.UtcNow.ToString("o")+" "+s+Environment.NewLine);try{using(var k=Registry.LocalMachine.CreateSubKey(@"SOFTWARE\Microsoft\Virtual Machine\Guest"))k.SetValue("ScriptStudioStatus",s.Length>1000?s.Substring(0,1000):s);}catch(UnauthorizedAccessException){}}
static void Pass(string s){passed.Add(s);Status("PASS "+s);File.WriteAllText(Path.Combine(results,"checks.json"),json.Serialize(passed));}
static void Assert(bool b,string s){if(!b)throw new Exception(s);}
static Dictionary<string,object> Read(string p){return json.Deserialize<Dictionary<string,object>>(File.ReadAllText(p));}
static void Wait(Func<bool> f,int seconds,string reason){for(int i=0;i<seconds;i++){if(f())return;Thread.Sleep(1000);}throw new Exception("Timeout: "+reason);}
static AutomationElement Find(string n){return root.FindFirst(TreeScope.Descendants,new PropertyCondition(AutomationElement.NameProperty,n));}
static void Click(string n){var e=Find(n);Assert(e!=null&&e.Current.IsEnabled,"Unavailable: "+n);((InvokePattern)e.GetCurrentPattern(InvokePattern.Pattern)).Invoke();}
static string ReportText(){foreach(AutomationElement e in root.FindAll(TreeScope.Descendants,Condition.TrueCondition)){object v;string text=null;if(e.TryGetCurrentPattern(ValuePattern.Pattern,out v))text=((ValuePattern)v).Current.Value;else if(e.TryGetCurrentPattern(TextPattern.Pattern,out v))text=((TextPattern)v).DocumentRange.GetText(-1);if(text!=null&&text.Length>200)return text;}return "Setup report unavailable through UI Automation";}
static void Close(){((WindowPattern)root.GetCurrentPattern(WindowPattern.Pattern)).Close();Thread.Sleep(2000);}
static void Screenshot(string name){var b=Screen.PrimaryScreen.Bounds;using(var img=new Bitmap(b.Width,b.Height))using(var g=Graphics.FromImage(img)){g.CopyFromScreen(b.Location,Point.Empty,b.Size);img.Save(Path.Combine(results,name+".png"));}}
static string Hash(string p){using(var s=File.OpenRead(p))using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
static void Wizard(bool cancel){var p=Process.Start(new ProcessStartInfo(setup){UseShellExecute=false});Wait(()=>{p.Refresh();return p.MainWindowHandle!=IntPtr.Zero;},300,"setup window");root=AutomationElement.FromHandle(p.MainWindowHandle);foreach(string button in new[]{"Scan / Review","Accept and install","Launch"}){var item=Find(button);Assert(item!=null&&!item.Current.IsOffscreen&&item.Current.BoundingRectangle.Bottom<=Screen.PrimaryScreen.WorkingArea.Bottom,"Wizard action clipped on guest display: "+button);}Assert(!Find("Accept and install").Current.IsEnabled,"Install enabled without acceptance");Click("Scan / Review");Thread.Sleep(2000);Wait(()=>Find("Scan / Review").Current.IsEnabled,180,"inventory");
var edits=root.FindAll(TreeScope.Descendants,new PropertyCondition(AutomationElement.ControlTypeProperty,ControlType.Edit));bool a=false,s=false;foreach(AutomationElement e in edits){object v;if(e.TryGetCurrentPattern(ValuePattern.Pattern,out v)){var vp=(ValuePattern)v;var text=vp.Current.Value;a|=text==app;s|=text==storage;if(vp.Current.IsReadOnly)File.WriteAllText(Path.Combine(results,"accounting.txt"),text);}}Assert(a&&s,"Default paths mismatch");File.WriteAllText(Path.Combine(results,"accounting.txt"),ReportText());
var toggle=(TogglePattern)Find("I reviewed the accounting report and accept the selected installation actions and licenses.").GetCurrentPattern(TogglePattern.Pattern);Assert(toggle.Current.ToggleState==ToggleState.Off,"Preselected acceptance");Assert(!Find("Accept and install").Current.IsEnabled,"Install before acceptance");if(!Directory.Exists(app)&&!Directory.Exists(storage))Pass("Inventory created no application or storage files");
toggle.Toggle();Thread.Sleep(500);Click("Accept and install");if(cancel){Thread.Sleep(2000);Click("Cancel");Wait(()=>Find("Scan / Review").Current.IsEnabled,900,"cancel completion");Assert(Convert.ToString(Read(Path.Combine(storage,"setup-journal.json"))["phase"])=="canceled","Cancellation journal");Close();Pass("Cancellation recorded durably");return;}
Wait(()=>Find("Launch").Current.IsEnabled||Find("Scan / Review").Current.IsEnabled,1800,"install verification");if(!Find("Launch").Current.IsEnabled){Screenshot("failure");File.WriteAllText(Path.Combine(results,"wizard-failure.txt"),ReportText());foreach(AutomationElement e in edits){object v;if(e.TryGetCurrentPattern(ValuePattern.Pattern,out v)&&((ValuePattern)v).Current.IsReadOnly)File.WriteAllText(Path.Combine(results,"wizard-failure.txt"),((ValuePattern)v).Current.Value);}throw new Exception("Install failed; see wizard-failure.txt");}
Assert(Convert.ToString(Read(Path.Combine(storage,"setup-journal.json"))["phase"])=="complete","Journal incomplete");var accepted=(Dictionary<string,object>)Read(Path.Combine(storage,"setup-acceptance.json"))["plan"];Assert(Convert.ToInt64(accepted["remaining_download_bytes"])==0,"Unexpected core downloads");Assert(((System.Collections.ICollection)accepted["selected"]).Count==0,"Optional feature selected");File.Copy(Path.Combine(storage,"setup-verification.json"),Path.Combine(results,"setup-verification.json"),true);Pass("Offline wizard installation and built-in database/narration/MP4/subtitles/OpenShot verification");Screenshot("installed-wizard");Click("Launch");Thread.Sleep(2000);Close();}
static string Api(string method,string route,string body=null){var r=(HttpWebRequest)WebRequest.Create(url+route);r.Proxy=null;r.Method=method;r.ContentType="application/json";r.Timeout=15000;if(body!=null){var bytes=Encoding.UTF8.GetBytes(body);using(var s=r.GetRequestStream())s.Write(bytes,0,bytes.Length);}using(var response=r.GetResponse())using(var reader=new StreamReader(response.GetResponseStream()))return reader.ReadToEnd();}
static void Ready(){Wait(()=>File.Exists(Path.Combine(storage,"data","ready.json")),300,"installed app startup");url=(string)Read(Path.Combine(storage,"data","ready.json"))["url"];Assert(Api("GET","/api/health").Contains("\"ok\""),"Health endpoint");Wait(()=>Directory.Exists(Path.Combine(storage,"data","browser","Default")),60,"browser profile");Pass("Installed application API and browser launch");Screenshot("application");}
static void Stop(){string data=Path.Combine(storage,"data");File.WriteAllText(Path.Combine(data,"stop.request"),"stop");Wait(()=>!File.Exists(Path.Combine(data,"ready.json")),180,"graceful stop");foreach(var p in Process.GetProcessesByName("ScriptStudio"))try{p.CloseMainWindow();}catch{}Thread.Sleep(3000);}
[STAThread]static int Main(){app=Path.Combine(home,"Programs","ScriptStudio");storage=Path.Combine(home,"ScriptStudio");try{Directory.CreateDirectory(results);string phase=Path.Combine(results,"phase.txt");
if(!File.Exists(phase)){Status("READY_FOR_BASELINE_CHECKPOINT");Wait(()=>File.Exists(Path.Combine(results,"start.flag")),1800,"host start flag");
Assert(!Directory.Exists(app)&&!Directory.Exists(storage),"Not a clean destination");foreach(string cmd in new[]{"python.exe","psql.exe","ffmpeg.exe","docker.exe","git.exe","node.exe"}){var p=Process.Start(new ProcessStartInfo("where.exe",cmd){UseShellExecute=false,CreateNoWindow=true,RedirectStandardOutput=true,RedirectStandardError=true});p.WaitForExit();var paths=p.StandardOutput.ReadToEnd().Split(new[]{'\r','\n'},StringSplitOptions.RemoveEmptyEntries);bool storeAlias=cmd=="python.exe"&&paths.Length>0&&paths.All(path=>string.Equals(path.Trim(),Path.Combine(home,"Microsoft","WindowsApps","python.exe"),StringComparison.OrdinalIgnoreCase));Assert(p.ExitCode!=0||storeAlias,"Preinstalled dependency: "+cmd);if(storeAlias)Pass("Built-in Windows Python Store shortcut is not an installed runtime");}using(var search=new ManagementObjectSearcher("SELECT Name,NetEnabled FROM Win32_NetworkAdapter WHERE NetEnabled=True"))Assert(search.Get().Count==0,"Guest network must be disconnected");Pass("Clean Windows guest has no development tools or external networking");
var drive=DriveInfo.GetDrives().First(d=>d.DriveType==DriveType.CDRom&&File.Exists(Path.Combine(d.RootDirectory.FullName,"ScriptStudio-Setup.exe")));setup=Path.Combine(drive.RootDirectory.FullName,"ScriptStudio-Setup.exe");Assert(Hash(setup)==Convert.ToString(Read(Path.Combine(drive.RootDirectory.FullName,"candidate.json"))["sha256"]),"Installer checksum");File.Copy(setup,Path.Combine(results,"ScriptStudio-Setup.exe"),true);setup=Path.Combine(results,"ScriptStudio-Setup.exe");Pass("Release EXE checksum matches");Wizard(true);Wizard(false);Ready();
var project=ReadProject(Api("POST","/api/projects","{\"name\":\"VM restart durability check\",\"script\":\"[Sunrise] Preserve this project across restart and repair.\"}"));File.WriteAllText(Path.Combine(results,"project-id.txt"),(string)project["id"]);Pass("Created persistent project");Stop();
if(!string.Equals(System.Reflection.Assembly.GetExecutingAssembly().Location,Path.Combine(results,"GuestChecks.exe"),StringComparison.OrdinalIgnoreCase))File.Copy(System.Reflection.Assembly.GetExecutingAssembly().Location,Path.Combine(results,"GuestChecks.exe"),true);File.WriteAllText(phase,"restart");using(var k=Registry.CurrentUser.CreateSubKey(@"Software\Microsoft\Windows\CurrentVersion\RunOnce"))k.SetValue("ScriptStudioVmChecks","\""+Path.Combine(results,"GuestChecks.exe")+"\"");Status("REBOOTING_FOR_DURABILITY_TEST");Process.Start("shutdown.exe","/r /t 5");return 0;
}else{passed=json.Deserialize<List<string>>(File.ReadAllText(Path.Combine(results,"checks.json")));setup=Path.Combine(results,"ScriptStudio-Setup.exe");Status("RESTART_DURABILITY_TEST");string launcher=Path.Combine((string)Read(Path.Combine(app,"active.json"))["directory"],"ScriptStudio.exe");Process.Start(new ProcessStartInfo(launcher,"--start"){UseShellExecute=false});Ready();string id=File.ReadAllText(Path.Combine(results,"project-id.txt"));Assert(Api("GET","/api/projects/"+id).Contains("VM restart durability check"),"Project lost on restart");Pass("Project survived actual Windows reboot");Stop();
string package=Directory.GetDirectories(Path.Combine(storage,"packages")).First(d=>File.Exists(Path.Combine(d,"file-inventory.json")));string index=Path.Combine(package,"web","index.html");Assert(File.Exists(index),"Repair fixture missing");string good=Hash(index);File.AppendAllText(index,"\nCORRUPTED_VM_REPAIR_FIXTURE");Status("TESTING_CORRUPTED_CACHE_REPAIR");using(var p=Process.Start(new ProcessStartInfo(launcher,"--verify"){UseShellExecute=false})){Assert(p.WaitForExit(900000)&&p.ExitCode==0,"Cache repair failed");}Assert(Hash(index)==good,"Cache not restored");Pass("Corrupted extracted file repaired from embedded payload");Wizard(false);Ready();Assert(Api("GET","/api/projects/"+id).Contains("VM restart durability check"),"Project lost on repair");Assert(Directory.GetDirectories(Path.Combine(storage,"backups")).Length>0,"Missing database backup");Pass("Installer repair preserved project and backed up database");File.WriteAllText(phase,"complete");Status("COMPLETE: "+passed.Count+" checks passed");return 0;}
}catch(Exception e){File.WriteAllText(Path.Combine(results,"failure.txt"),e.ToString());try{Screenshot("failure");}catch{}Status("FAILED: "+e.Message);return 1;}}
static Dictionary<string,object> ReadProject(string s){return json.Deserialize<Dictionary<string,object>>(s);}
}
